static void set_fen(Pos*p,const char*fen){
    memset(p->sq,0,sizeof(p->sq));
    int r=7,f=0; const char*c=fen;
    while(*c&&*c!=' '){
        if(*c=='/'){r--;f=0;}
        else if(*c>='1'&&*c<='8')f+=*c-'0';
        else{ int t=0,col=(*c>='a'); char u=*c|32;
            t= u=='p'?P:u=='n'?N:u=='b'?B:u=='r'?R:u=='q'?Q:K;
            p->sq[r*16+f]=MK(t,col); if(t==K)p->ksq[col]=r*16+f; f++; }
        c++;
    }
    while(*c==' ')c++;
    p->side=(*c=='b'); c++; while(*c==' ')c++;
    p->castle=0;
    while(*c&&*c!=' '){ if(*c=='K')p->castle|=1; if(*c=='Q')p->castle|=2; if(*c=='k')p->castle|=4; if(*c=='q')p->castle|=8; c++; }
    while(*c==' ')c++;
    p->ep=-1; if(*c&&*c!='-'){ p->ep=parse_sq(c); c+=2; } else if(*c)c++;
