static int attacked(Pos*p,int s,int by){
    int pawn=MK(P,by);
    if(by==WHITE){ if(ONBOARD(s-15)&&p->sq[s-15]==pawn)return 1; if(ONBOARD(s-17)&&p->sq[s-17]==pawn)return 1; }
    else { if(ONBOARD(s+15)&&p->sq[s+15]==pawn)return 1; if(ONBOARD(s+17)&&p->sq[s+17]==pawn)return 1; }
    int kn=MK(N,by),kg=MK(K,by);
    for(int i=0;i<8;i++){ int t=s+ndir[i]; if(ONBOARD(t)&&p->sq[t]==kn)return 1; t=s+kdir[i]; if(ONBOARD(t)&&p->sq[t]==kg)return 1; }
    int bi=MK(B,by),qu=MK(Q,by),ro=MK(R,by);
    for(int i=0;i<4;i++){ int t=s+bdir[i]; while(ONBOARD(t)){ int q=p->sq[t]; if(q){ if(q==bi||q==qu)return 1; break;} t+=bdir[i]; } }
    for(int i=0;i<4;i++){ int t=s+rdir[i]; while(ONBOARD(t)){ int q=p->sq[t]; if(q){ if(q==ro||q==qu)return 1; break;} t+=rdir[i]; } }
    return 0;
}
