            }
            for(int d=-1;d<=1;d+=2){ to=s+fwd+d; if(!ONBOARD(to))continue;
                if(p->sq[to]&&COL(p->sq[to])==them){
                    if((to>>4)==prom_rank){ for(int pr=Q;pr>=N;pr--)moves[n++]=MKMOVE(s,to,pr,F_CAP); }
                    else moves[n++]=MKMOVE(s,to,0,F_CAP);
                } else if(to==p->ep) moves[n++]=MKMOVE(s,to,0,F_EP|F_CAP);
            }
        } else if(t==N||t==K){
            const int*d=t==N?ndir:kdir;
            for(int i=0;i<8;i++){ int to=s+d[i]; if(!ONBOARD(to))continue; int q=p->sq[to];
                if(!q){ if(!caps_only)moves[n++]=MKMOVE(s,to,0,0); } else if(COL(q)==them)moves[n++]=MKMOVE(s,to,0,F_CAP); }
            if(t==K&&!caps_only){
                if(us==WHITE){
                    if((p->castle&1)&&!p->sq[5]&&!p->sq[6]&&p->sq[7]==MK(R,WHITE)&&!attacked(p,4,BLACK)&&!attacked(p,5,BLACK)&&!attacked(p,6,BLACK))moves[n++]=MKMOVE(4,6,0,F_CASTLE);
                    if((p->castle&2)&&!p->sq[3]&&!p->sq[2]&&!p->sq[1]&&p->sq[0]==MK(R,WHITE)&&!attacked(p,4,BLACK)&&!attacked(p,3,BLACK)&&!attacked(p,2,BLACK))moves[n++]=MKMOVE(4,2,0,F_CASTLE);
                } else {
                    if((p->castle&4)&&!p->sq[0x75]&&!p->sq[0x76]&&p->sq[0x77]==MK(R,BLACK)&&!attacked(p,0x74,WHITE)&&!attacked(p,0x75,WHITE)&&!attacked(p,0x76,WHITE))moves[n++]=MKMOVE(0x74,0x76,0,F_CASTLE);
                    if((p->castle&8)&&!p->sq[0x73]&&!p->sq[0x72]&&!p->sq[0x71]&&p->sq[0x70]==MK(R,BLACK)&&!attacked(p,0x74,WHITE)&&!attacked(p,0x73,WHITE)&&!attacked(p,0x72,WHITE))moves[n++]=MKMOVE(0x74,0x72,0,F_CASTLE);
                }
            }
        } else {
            int nd=(t==Q)?8:4; const int*d1=bdir,*d2=rdir;
            for(int i=0;i<nd;i++){ int dd= t==B?bdir[i]: t==R?rdir[i]: (i<4?d1[i]:d2[i-4]);
                int to=s+dd; while(ONBOARD(to)){ int q=p->sq[to]; if(!q){ if(!caps_only)moves[n++]=MKMOVE(s,to,0,0); } else { if(COL(q)==them)moves[n++]=MKMOVE(s,to,0,F_CAP); break; } to+=dd; } }
        }
    }
    return n;
}

static void put(Pos*p,int s,int pc){ p->sq[s]=pc; p->hash^=zob[pc][s]; }
static void clr(Pos*p,int s){ p->hash^=zob[p->sq[s]][s]; p->sq[s]=0; }

static int make_move(Pos*p,int m){
    int from=MFROM(m),to=MTO(m),promo=MPROMO(m),fl=MFLAGS(m);
    int us=p->side,them=us^1; int pc=p->sq[from];
    Undo*u=&p->undo[p->hist_n]; u->move=m; u->captured=p->sq[to]; u->ep=p->ep; u->castle=p->castle; u->half=p->half; u->hash=p->hash;
    p->hist[p->hist_n++]=p->hash;
    p->half++;
    if(p->ep>=0)p->hash^=zobep[p->ep]; p->ep=-1;
    if(u->captured){ clr(p,to); p->half=0; }
    if(fl&F_EP){ int cs=us==WHITE?to-16:to+16; clr(p,cs); }
    clr(p,from);
    if(promo)put(p,to,MK(promo,us)); else put(p,to,pc);
    if(TYP(pc)==P){ p->half=0; if(fl&F_DPUSH){ p->ep=us==WHITE?from+16:from-16; p->hash^=zobep[p->ep]; } }
    if(TYP(pc)==K){ p->ksq[us]=to;
        if(fl&F_CASTLE){ if(to==6){clr(p,7);put(p,5,MK(R,WHITE));} else if(to==2){clr(p,0);put(p,3,MK(R,WHITE));}
            else if(to==0x76){clr(p,0x77);put(p,0x75,MK(R,BLACK));} else {clr(p,0x70);put(p,0x73,MK(R,BLACK));} } }
    p->hash^=zobcastle[p->castle]; p->castle&=castle_mask[from]&castle_mask[to]; p->hash^=zobcastle[p->castle];
    p->side=them; p->hash^=zobside; p->ply++;
    if(attacked(p,p->ksq[us],them)) return 0;
    return 1;
}
static void unmake_move(Pos*p){
    Undo*u=&p->undo[--p->hist_n]; int m=u->move;
    int from=MFROM(m),to=MTO(m),promo=MPROMO(m),fl=MFLAGS(m);
    p->side^=1; p->ply--; int us=p->side;
    int pc=p->sq[to]; if(promo)pc=MK(P,us);
    p->sq[to]=u->captured; p->sq[from]=pc;
    if(fl&F_EP){ int cs=us==WHITE?to-16:to+16; p->sq[cs]=MK(P,us^1); }
    if(TYP(pc)==K){ p->ksq[us]=from;
        if(fl&F_CASTLE){ if(to==6){p->sq[7]=MK(R,WHITE);p->sq[5]=0;} else if(to==2){p->sq[0]=MK(R,WHITE);p->sq[3]=0;}
            else if(to==0x76){p->sq[0x77]=MK(R,BLACK);p->sq[0x75]=0;} else {p->sq[0x70]=MK(R,BLACK);p->sq[0x73]=0;} } }
    p->ep=u->ep; p->castle=u->castle; p->half=u->half; p->hash=u->hash;
}
static void make_null(Pos*p){ Undo*u=&p->undo[p->hist_n]; u->move=0; u->ep=p->ep; u->hash=p->hash; u->half=p->half; u->castle=p->castle; u->captured=0; p->hist[p->hist_n++]=p->hash;
    if(p->ep>=0)p->hash^=zobep[p->ep]; p->ep=-1; p->side^=1; p->hash^=zobside; p->ply++; }
static void unmake_null(Pos*p){ Undo*u=&p->undo[--p->hist_n]; p->side^=1; p->ply--; p->ep=u->ep; p->hash=u->hash; }

/* Evaluation */
static int evaluate(Pos*p){
    int mg[2]={0,0},eg[2]={0,0},phase=0; int bishops[2]={0,0};
    int pawns_file[2][8]; memset(pawns_file,0,sizeof(pawns_file));
    int npm[2]={0,0};
    for(int s=0;s<128;s++){ if(!ONBOARD(s))continue; int pc=p->sq[s]; if(!pc)continue; int c=COL(pc),t=TYP(pc);
        mg[c]+=mg_pst[pc][s]; eg[c]+=eg_pst[pc][s]; phase+=phase_inc[t];
        if(t==B)bishops[c]++; if(t==P)pawns_file[c][s&7]++; if(t!=P&&t!=K)npm[c]+=mg_val[t];
    }
    for(int c=0;c<2;c++){ if(bishops[c]>=2){mg[c]+=25;eg[c]+=45;}
        for(int f=0;f<8;f++){ int n=pawns_file[c][f]; if(n>1){mg[c]-=10*(n-1);eg[c]-=20*(n-1);}
            if(n&&(f==0||!pawns_file[c][f-1])&&(f==7||!pawns_file[c][f+1])){mg[c]-=8*n;eg[c]-=15*n;} }
    }
    /* passed pawns & rook on open file, simple */
    for(int s=0;s<128;s++){ if(!ONBOARD(s))continue; int pc=p->sq[s]; if(!pc)continue; int c=COL(pc),t=TYP(pc),f=s&7,r=s>>4;
        if(t==P){ int passed=1; int rr= c==WHITE?r:7-r;
            for(int ff=f-1;ff<=f+1;ff++){ if(ff<0||ff>7)continue;
                if(c==WHITE){ for(int r2=r+1;r2<8;r2++) if(p->sq[r2*16+ff]==MK(P,BLACK)){passed=0;break;} }
                else { for(int r2=r-1;r2>=0;r2--) if(p->sq[r2*16+ff]==MK(P,WHITE)){passed=0;break;} }
                if(!passed)break; }
            if(passed){ static const int pb[8]={0,5,10,20,35,60,100,0}; mg[c]+=pb[rr]/2; eg[c]+=pb[rr]; }
        } else if(t==R){ if(!pawns_file[c][f]){ mg[c]+=pawns_file[c^1][f]?10:20; eg[c]+=pawns_file[c^1][f]?5:10; } }
    }
    /* king safety: pawn shield in middlegame */
    for(int c=0;c<2;c++){ int ks=p->ksq[c]; int kf=ks&7,kr=ks>>4; int shield=0; int fwd=c==WHITE?16:-16;
        for(int ff=kf-1;ff<=kf+1;ff++){ if(ff<0||ff>7)continue; int s1=kr*16+ff+fwd; if(ONBOARD(s1)&&p->sq[s1]==MK(P,c))shield++; else { int s2=s1+fwd; if(ONBOARD(s2)&&p->sq[s2]==MK(P,c))shield++; } }
        mg[c]+=shield*12;
        /* enemy queen present increases importance */
    }
    if(phase>24)phase=24;
    int us=p->side,them=us^1;
    int mgs=mg[us]-mg[them],egs=eg[us]-eg[them];
    int score=(mgs*phase+egs*(24-phase))/24;
    /* draw-ish scaling: no pawns and little material */
    return score+10; /* tempo */
}

/* Transposition table */
typedef struct { U64 key; int32_t move; int16_t score; int8_t depth; uint8_t flag; } TTE;
#define TT_EXACT 1
#define TT_ALPHA 2
#define TT_BETA 3
static TTE*tt; static U64 tt_size;
static void tt_init(size_t mb){ tt_size=(mb*1024*1024)/sizeof(TTE); U64 s=1; while(s*2<=tt_size)s*=2; tt_size=s; tt=calloc(tt_size,sizeof(TTE)); }
static inline TTE*tt_probe(U64 key){ TTE*e=&tt[key&(tt_size-1)]; return e->key==key?e:NULL; }
static inline void tt_store(U64 key,int move,int score,int depth,int flag){ TTE*e=&tt[key&(tt_size-1)];
    if(e->key==key&&e->depth>depth&&flag!=TT_EXACT)return;
    e->key=key; e->move=move; e->score=score; e->depth=depth; e->flag=flag; }

/* Search */
typedef struct {
    Pos pos;
