    int id;
    int stop;
    int best_move; int best_score; int depth_done;
    int pv[MAXPLY];
} Thread;

static volatile int stop_all=0;
static double time_limit; static struct timespec t_start;
static double now(){ struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return (t.tv_sec-t_start.tv_sec)+(t.tv_nsec-t_start.tv_nsec)*1e-9; }

static int is_repetition(Pos*p){ int cnt=0; for(int i=p->hist_n-2;i>=0&&i>=p->hist_n-p->half-1;i-=2) if(p->hist[i]==p->hash){ return 1; } return cnt; }

static int mvv_lva(Pos*p,int m){ int v=TYP(p->sq[MTO(m)]); int a=TYP(p->sq[MFROM(m)]); if(MFLAGS(m)&F_EP)v=P; return v*10-a; }

static int quiesce(Thread*th,int alpha,int beta){
    Pos*p=&th->pos; th->nodes++;
    if((th->nodes&4095)==0){ if(now()>time_limit)stop_all=1; }
    if(stop_all)return 0;
    int stand=evaluate(p);
    if(p->ply>=MAXPLY-1)return stand;
    if(stand>=beta)return stand;
    if(stand>alpha)alpha=stand;
    int moves[256]; int n=gen_moves(p,moves,1); int scores[256];
    for(int i=0;i<n;i++)scores[i]=mvv_lva(p,moves[i])+(MPROMO(moves[i])==Q?50:0);
    for(int i=0;i<n;i++){
        int bi=i; for(int j=i+1;j<n;j++)if(scores[j]>scores[bi])bi=j;
        int tm=moves[i];moves[i]=moves[bi];moves[bi]=tm; int ts=scores[i];scores[i]=scores[bi];scores[bi]=ts;
        int m=moves[i];
        /* delta pruning */
        int capv= (MFLAGS(m)&F_EP)?mg_val[P]:mg_val[TYP(p->sq[MTO(m)])];
        if(!MPROMO(m)&&stand+capv+200<alpha)continue;
        if(!make_move(p,m)){unmake_move(p);continue;}
        int sc=-quiesce(th,-beta,-alpha);
        unmake_move(p);
        if(stop_all)return 0;
        if(sc>alpha){ alpha=sc; if(sc>=beta)return sc; }
    }
    return alpha;
}

static int search(Thread*th,int depth,int alpha,int beta,int do_null){
    Pos*p=&th->pos;
    int pvnode=(beta-alpha>1);
    if(p->ply>0&&(is_repetition(p)||p->half>=100))return 0;
    int incheck=in_check(p);
    if(incheck)depth++;
    if(depth<=0)return quiesce(th,alpha,beta);
    th->nodes++;
    if((th->nodes&4095)==0){ if(now()>time_limit)stop_all=1; }
    if(stop_all)return 0;
    if(p->ply>=MAXPLY-1)return evaluate(p);
    /* mate distance pruning */
    { int ma=-MATE+p->ply, mb=MATE-p->ply-1; if(alpha<ma)alpha=ma; if(beta>mb)beta=mb; if(alpha>=beta)return alpha; }
    int ttmove=0; TTE*e=tt_probe(p->hash);
    if(e){ ttmove=e->move;
        if(!pvnode&&e->depth>=depth){ int sc=e->score; if(sc>MATE-200)sc-=p->ply; else if(sc<-MATE+200)sc+=p->ply;
            if(e->flag==TT_EXACT)return sc; if(e->flag==TT_ALPHA&&sc<=alpha)return sc; if(e->flag==TT_BETA&&sc>=beta)return sc; } }
    int stat=evaluate(p);
    /* reverse futility */
    if(!pvnode&&!incheck&&depth<=6&&stat-80*depth>=beta&&abs(beta)<MATE-200)return stat;
    /* null move */
    if(do_null&&!pvnode&&!incheck&&depth>=3&&stat>=beta){
        int has_piece=0; for(int s=0;s<128&&!has_piece;s++)if(ONBOARD(s)&&p->sq[s]&&COL(p->sq[s])==p->side&&TYP(p->sq[s])!=P&&TYP(p->sq[s])!=K)has_piece=1;
        if(has_piece){ make_null(p); int R_=3+depth/6; int sc=-search(th,depth-1-R_,-beta,-beta+1,0); unmake_null(p);
            if(stop_all)return 0; if(sc>=beta&&abs(sc)<MATE-200)return beta; }
    }
    /* IID */
    if(!ttmove&&depth>=5&&pvnode){ search(th,depth-2,alpha,beta,0); e=tt_probe(p->hash); if(e)ttmove=e->move; }
    int moves[256],scores[256]; int n=gen_moves(p,moves,0);
    for(int i=0;i<n;i++){ int m=moves[i]; int s;
        if(m==ttmove)s=1000000; else if(MFLAGS(m)&F_CAP)s=100000+mvv_lva(p,m)*100; else if(MPROMO(m))s=90000+MPROMO(m);
        else if(m==th->killers[p->ply][0])s=80000; else if(m==th->killers[p->ply][1])s=79000;
        else s=th->history[p->side][MFROM(m)][MTO(m)];
        scores[i]=s; }
    int best=-INF,bestmove=0,legal=0,flag=TT_ALPHA; int oldalpha=alpha;
    for(int i=0;i<n;i++){
        int bi=i; for(int j=i+1;j<n;j++)if(scores[j]>scores[bi])bi=j;
        int tm=moves[i];moves[i]=moves[bi];moves[bi]=tm; int ts=scores[i];scores[i]=scores[bi];scores[bi]=ts;
        int m=moves[i]; int quiet=!(MFLAGS(m)&F_CAP)&&!MPROMO(m);
        /* futility pruning */
        if(!pvnode&&!incheck&&quiet&&depth<=3&&legal>0&&stat+150*depth<=alpha&&abs(alpha)<MATE-200)continue;
        /* late move pruning */
        if(!pvnode&&!incheck&&quiet&&depth<=3&&legal>4+depth*depth)continue;
        if(!make_move(p,m)){unmake_move(p);continue;}
        legal++;
        int sc;
        int gives_check=in_check(p);
        if(legal==1) sc=-search(th,depth-1,-beta,-alpha,1);
        else {
            int red=0;
            if(quiet&&depth>=3&&legal>3&&!gives_check){ red=1+(legal>8)+(depth>6); if(pvnode)red--; if(red<0)red=0; }
            sc=-search(th,depth-1-red,-alpha-1,-alpha,1);
            if(red&&sc>alpha&&!stop_all) sc=-search(th,depth-1,-alpha-1,-alpha,1);
            if(sc>alpha&&sc<beta&&!stop_all) sc=-search(th,depth-1,-beta,-alpha,1);
        }
        unmake_move(p);
        if(stop_all)return 0;
        if(sc>best){ best=sc; bestmove=m;
            if(sc>alpha){ alpha=sc; flag=TT_EXACT;
                if(sc>=beta){ flag=TT_BETA;
                    if(quiet){ if(th->killers[p->ply][0]!=m){th->killers[p->ply][1]=th->killers[p->ply][0];th->killers[p->ply][0]=m;}
                        th->history[p->side][MFROM(m)][MTO(m)]+=depth*depth; if(th->history[p->side][MFROM(m)][MTO(m)]>60000){ for(int a=0;a<128;a++)for(int b=0;b<128;b++)th->history[p->side][a][b]/=2; } }
                    break; } } }
    }
    if(!legal) return incheck? -MATE+p->ply : 0;
    { int sc=best; if(sc>MATE-200)sc+=p->ply; else if(sc<-MATE+200)sc-=p->ply; tt_store(p->hash,bestmove,sc,depth,flag==TT_ALPHA?TT_ALPHA:(best>=beta?TT_BETA:(alpha>oldalpha?TT_EXACT:TT_ALPHA))); }
    return best;
}

static Thread threads[64]; static int nthreads=1; static int max_depth=64;

static void print_pv(Pos*p,int depth){
    Pos tmp=*p; char b[8]; int cnt=0;
    for(int i=0;i<depth;i++){ TTE*e=tt_probe(tmp.hash); if(!e||!e->move)break; int m=e->move;
        int moves[256]; int n=gen_moves(&tmp,moves,0); int ok=0; for(int j=0;j<n;j++)if(moves[j]==m)ok=1; if(!ok)break;
        if(!make_move(&tmp,m)){break;}
        sq_str(MFROM(m),b); printf(" %s",b); sq_str(MTO(m),b); printf("%s",b); if(MPROMO(m))printf("%c","  nbrq"[MPROMO(m)]); cnt++; if(cnt>=MAXPLY-2)break; }
}

static void*thread_main(void*arg){
    Thread*th=(Thread*)arg; Pos*p=&th->pos;
    int alpha=-INF,beta=INF; int score=0;
    for(int d=1;d<=max_depth;d++){
        int dd=d; if(th->id>0){ dd=d+(th->id%2); }
        if(dd>max_depth)dd=max_depth;
        int window=25;
        if(dd>=5){ alpha=score-window; beta=score+window; } else {alpha=-INF;beta=INF;}
        while(1){
            score=search(th,dd,alpha,beta,1);
            if(stop_all)break;
            if(score<=alpha){ alpha-=window; window*=2; if(window>600){alpha=-INF;} }
            else if(score>=beta){ beta+=window; window*=2; if(window>600){beta=INF;} }
            else break;
        }
        if(stop_all)break;
        TTE*e=tt_probe(p->hash); if(e&&e->move){ th->best_move=e->move; }
        th->best_score=score; th->depth_done=dd;
        if(th->id==0){
            printf("info depth %d score cp %d nodes %ld time %d pv",dd,score,th->nodes,(int)(now()*1000)); print_pv(p,dd); printf("\n"); fflush(stdout);
            if(abs(score)>MATE-200 && dd>=8) { stop_all=1; break; }
            if(now()>time_limit*0.55 && dd>=6) { stop_all=1; break; }
        }
    }
    return NULL;
}

static int move_from_str(Pos*p,const char*s){
    int from=parse_sq(s),to=parse_sq(s+2); int promo=0;
    if(s[4]&&s[4]!=' '&&s[4]!='\n'){ char c=s[4]|32; promo=c=='q'?Q:c=='r'?R:c=='b'?B:N; }
    int moves[256]; int n=gen_moves(p,moves,0);
    for(int i=0;i<n;i++)if(MFROM(moves[i])==from&&MTO(moves[i])==to&&MPROMO(moves[i])==promo)return moves[i];
    return 0;
}

static Pos root;

static void go(double ms){
    clock_gettime(CLOCK_MONOTONIC,&t_start); time_limit=ms/1000.0; stop_all=0;
    for(int i=0;i<nthreads;i++){ threads[i].pos=root; threads[i].id=i; threads[i].nodes=0; threads[i].best_move=0; threads[i].best_score=0; threads[i].depth_done=0;
        memset(threads[i].killers,0,sizeof(threads[i].killers)); memset(threads[i].history,0,sizeof(threads[i].history)); }
    pthread_t tid[64];
    for(int i=1;i<nthreads;i++)pthread_create(&tid[i],NULL,thread_main,&threads[i]);
    thread_main(&threads[0]);
    stop_all=1;
    for(int i=1;i<nthreads;i++)pthread_join(tid[i],NULL);
    int bm=threads[0].best_move;
    /* pick from deepest thread */
    int bd=threads[0].depth_done; for(int i=1;i<nthreads;i++) if(threads[i].depth_done>bd&&threads[i].best_move){bd=threads[i].depth_done;bm=threads[i].best_move;}
    if(!bm){ int moves[256]; int n=gen_moves(&root,moves,0); for(int i=0;i<n;i++){ if(make_move(&root,moves[i])){unmake_move(&root);bm=moves[i];break;} unmake_move(&root);} }
    char b1[8],b2[8]; sq_str(MFROM(bm),b1); sq_str(MTO(bm),b2);
    printf("bestmove %s%s",b1,b2); if(MPROMO(bm))printf("%c","  nbrq"[MPROMO(bm)]); printf("\n"); fflush(stdout);
}

